@st.cache_resource(show_spinner=False)
def _finance_prepare_bundle(payload, digest, namespace):
    data = base64.b64decode(payload)
    if hashlib.sha256(data).hexdigest() != digest:
        raise RuntimeError("The deployment file is incomplete. Upload the original finance_app.py again.")
    temporary_directory = tempfile.TemporaryDirectory(prefix="finance-apps-")
    root = Path(temporary_directory.name).resolve()
    with ZipFile(io.BytesIO(data)) as archive:
        for name in archive.namelist():
            if not (root / name).resolve().is_relative_to(root):
                raise RuntimeError("Invalid bundled file path.")
        archive.extractall(root)
    # A version-specific package avoids collisions with files from older uploads.
    spec = importlib.util.spec_from_file_location(
        namespace, root / "__init__.py", submodule_search_locations=[str(root)]
    )
    module = importlib.util.module_from_spec(spec)
    sys.modules[namespace] = module
    spec.loader.exec_module(module)
    # Retain the temporary directory for the lifetime of the cached resource.
    return temporary_directory


_finance_runtime = _finance_prepare_bundle(_BUNDLE_DATA, _BUNDLE_DIGEST, _BUNDLE_NAMESPACE)


import streamlit as st

from _finance_bundle_97866dd9e67a21a8.finance_brand import apply_brand, render_footer, render_masthead


def arap() -> None:
    from _finance_bundle_97866dd9e67a21a8.arap_file_transformer.app import main as run_app

    run_app()


def pool() -> None:
    from _finance_bundle_97866dd9e67a21a8.invoice_pool_transformer.app import main as run_app

    run_app()


def accrual() -> None:
    from _finance_bundle_97866dd9e67a21a8.accrual_file_transformer.app import main as run_app

    run_app()


def render_home(app_pages) -> None:
    st.markdown('<div class="rc-eyebrow">Finance operations</div>', unsafe_allow_html=True)
    st.title("Finance Apps")
    st.markdown(
        '<p class="rc-intro">Prepare, validate and export your posting files. '
        'Choose the tool for your workflow.</p>', unsafe_allow_html=True,
    )
    descriptions = [
        "Select a posting month, generate company journals, and mark posted ARAP rows.",
        "Process AX or D365 invoice-pool workbooks and export rows marked yes.",
        "Transform an accrual workbook into separate AX and D365 posting files by company.",
    ]
    labels = ["Monthly postings", "Invoice-pool postings", "Accrual postings"]
    outputs = ["Company CSVs + marked workbook", "Company CSVs + combined ZIP", "Company CSVs + combined ZIP"]
    for index, (column, page, description) in enumerate(zip(st.columns(3), app_pages, descriptions)):
        with column:
            with st.container(border=True, key=f"finance-card-{page.url_path}"):
                st.markdown(
                    f'<div class="rc-card-label"><span class="rc-number">0{index + 1}</span>'
                    f'{labels[index]}</div>', unsafe_allow_html=True,
                )
                st.subheader(page.title)
                st.markdown(f'<p class="rc-card-description">{description}</p>', unsafe_allow_html=True)
                st.markdown(f'<div class="rc-card-output">{outputs[index]}</div>', unsafe_allow_html=True)
                st.page_link(page, label=f"Open {page.title} →", use_container_width=True)
    st.markdown(
        '<div class="rc-journey">'
        '<div class="rc-step"><span>01</span>Choose your tool</div>'
        '<div class="rc-step"><span>02</span>Upload your workbook</div>'
        '<div class="rc-step"><span>03</span>Download posting files</div></div>'
        '<div class="rc-help"><strong>Working in several tools?</strong> '
        'Open each tool in a separate browser tab to keep its uploads and inputs. '
        'Switching tools within one tab can reset your entries.</div>',
        unsafe_allow_html=True,
    )


def main() -> None:
    st.set_page_config(page_title="Finance Apps", page_icon="📄", layout="wide")
    apply_brand()
    app_pages = [
        st.Page(arap, title="ARAP", url_path="arap"),
        st.Page(pool, title="Pool", url_path="pool"),
        st.Page(accrual, title="ACCRUAL", url_path="accrual"),
    ]

    def home() -> None:
        render_home(app_pages)

    page = st.navigation(
        [st.Page(home, title="Home", default=True), *app_pages],
        position="top",
    )
    render_masthead()
    if page.url_path:
        st.markdown(
            f'<div class="rc-eyebrow">Finance operations / {page.title}</div>',
            unsafe_allow_html=True,
        )
        with st.container(key="finance-workspace"):
            page.run()
    else:
        page.run()
    render_footer()


if __name__ == "__main__":
    main()
